import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.Cu3jFwFD.js";const f=JSON.parse('{"title":"Run and quota","description":"","frontmatter":{},"headers":[],"relativePath":"features/run-and-quota/design.md","filePath":"features/run-and-quota/design.md","lastUpdated":1794907169000}'),o={name:"features/run-and-quota/design.md"};function n(d,e,i,h,l,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="run-and-quota" tabindex="-1">Run and quota <a class="header-anchor" href="#run-and-quota" aria-label="Permalink to &quot;Run and quota&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>A run is three normal days that all count toward one profit quota, then a boss day if the quota was met. The player is never shut out early, but the verdict on Day 3 decides everything: pass and face Charon, miss and start over from Day 1. Serves the pillar <strong>Push your luck</strong> (every extra delivery raises the profit and the risk of the trip home).</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li>A run is Day 1, Day 2 and Day 3 (normal days). Day 4 is the boss day and is played only if the quota is met after Day 3 (<a href="./../boss-charon/design">boss-charon</a>). (<a class="decision-ref" href="/hex-gdd/GDD#d-025">D‑025</a>)</li><li>Each day: Garage → Start → trial (Day 2–3) → map shift → end-of-day report → Garage. The next day starts when the report is closed. Net income of a day: <code>income = sum of paid deliveries</code>; if wrecked, <code>income -= overtimeEarned</code>, then <code>net = floor(income × 0.5)</code>; otherwise <code>net = income</code>. Then <code>profit += net; cash += net</code>.</li><li><strong>Profit</strong> is the net income banked at the end of each day. It counts toward the run quota and is never reduced by spending.</li><li><strong>Cash</strong> is the same net income, spendable in the Garage (repair, reroll, relics; see <a href="./../upgrades/design">upgrades</a>, <a href="./../damage-and-repair/design">damage-and-repair</a>). Spending lowers cash only.</li><li>There is <strong>one run quota</strong>, checked once, after the Day 3 report: profit ≥ quota continues to the boss, otherwise the run ends in game over. Days 1 and 2 have no pass or fail gate. The quota bar appears only on the report and in the Garage, not on the shift HUD (<a class="decision-ref" href="/hex-gdd/GDD#d-067">D‑067</a>).</li><li>A wrecked day (see <a href="./../damage-and-repair/design">damage-and-repair</a>) is marked FAILED but the run continues; only the kept share of its income reaches profit. A wrecked Day 3 still passes if profit meets the quota.</li><li>Game over (quota missed, or Iris wins the boss race) restarts from Day 1. Profit, cash, van HP, cards and relics all reset. There is no profile progress in the MVP.</li><li>Beating Charon ends the run on the ending screen (&quot;to be continued&quot;).</li><li>The end-of-day report shows, one row at a time: delivery income, overtime money forfeited (wreck only), wreck fine (wreck only), net, then the run quota bar before and after the day, then the verdict stamp (SUCCESS, FAILED, run failed, run complete).</li><li>Game over first shows one summary screen: the cause (&quot;quota missed by $X&quot; or &quot;Iris won 12–9&quot;), total money, the day reached and HP lost. Then the game-over cutscene and Try Again. (<a class="decision-ref" href="/hex-gdd/GDD#d-033">D‑033</a>)</li><li>Systems are introduced by day, in every run (<a class="decision-ref" href="/hex-gdd/GDD#d-044">D‑044</a>): Day 1 has Safe packages and Zeus&#39;s package (the scripted tutorial on the first run only); Day 2 adds Chance packages; Day 3 has everything.</li><li>There is no fine for packages left undelivered at the end of the day (<a class="decision-ref" href="/hex-gdd/GDD#d-045">D‑045</a>).</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Normal days</td><td>3</td><td>days</td><td>Run length vs the session target</td></tr><tr><td>Run quota</td><td>600 <mark class="tune">TUNE</mark></td><td>$ profit</td><td>Re-tune after the combo cut: the prototype quota was tuned with combo bonuses up to ×3</td></tr><tr><td>Normal shift length</td><td>60 (<a class="decision-ref" href="/hex-gdd/GDD#d-030">D‑030</a>)</td><td>s</td><td>Enough deliveries per day to feel generous without a nitro or combo</td></tr><tr><td>Boss shift length</td><td>120 <mark class="tune">TUNE</mark></td><td>s</td><td>See <a href="./../boss-charon/design">boss-charon</a></td></tr><tr><td>Net income floor</td><td>0</td><td>$</td><td>A day never subtracts from profit</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Profit is never negative: a day with no deliveries banks 0.</li><li>Quitting to the menu mid-run loses the run; there is no mid-run save (<a class="decision-ref" href="/hex-gdd/GDD#d-032">D‑032</a>).</li><li>Hitting the quota early (before Day 3) gives no early exit; the run still plays all three days.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><mark class="tune">TUNE</mark> Quota 600 is the prototype&#39;s value and must be re-tuned without combo.</li><li>Session length is settled at about 6–8 min (<a class="decision-ref" href="/hex-gdd/GDD#d-030">D‑030</a>); cash is all banked net income (<a class="decision-ref" href="/hex-gdd/GDD#d-031">D‑031</a>).</li><li>The old GDD&#39;s 7 days with a daily, rising quota is now a later option, not the MVP.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed from the prototype&#39;s run loop and the owner&#39;s decisions <a class="decision-ref" href="/hex-gdd/GDD#d-025">D‑025</a> (3 days + boss gate) and <a class="decision-ref" href="/hex-gdd/GDD#d-026">D‑026</a> (visible HP). Supersedes the old 7-day daily-quota run (<a class="decision-ref" href="/hex-gdd/GDD#d-013">D‑013</a>).</li></ul>',13)])])}const m=a(o,[["render",n]]);export{f as __pageData,m as default};
